from collections import defaultdict
from math import atan2, pi

def orientation(p, q, r):
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if val == 0:
        return 0  # collinear
    return 1 if val > 0 else 2  # clock or counterclock

def convex_hull(points):
    n = len(points)
    if n < 3:
        return points

    l = 0
    for i in range(1, n):
        if points[i][0] < points[l][0]:
            l = i

    hull = []
    p = l
    while True:
        hull.append(points[p])
        q = (p + 1) % n
        for i in range(n):
            if orientation(points[p], points[i], points[q]) == 2:
                q = i
        p = q
        if p == l:
            break

    return hull

def can_hit_all_targets_with_two_shots(N, targets):
    if N <= 2:
        return "success"

    hull = convex_hull(targets)
    if len(hull) <= 2:
        return "success"

    slope_count = defaultdict(int)

    for i in range(len(hull)):
        for j in range(i + 1, len(hull)):
            x1, y1 = hull[i]
            x2, y2 = hull[j]

            if x1 == x2:
                slope = float('inf')
            else:
                slope = atan2(y2 - y1, x2 - x1)

            slope_count[slope] += 1

    unique_slopes = len(slope_count)

    if unique_slopes > 2:
        return "failure"
    else:
        return "success"

